<?php $page='categories';require __DIR__.'/_head.php';$msg='';if(isset($_GET['delete'])){check_csrf();db()->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_GET['delete']]);header('Location:categories.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$n=trim($_POST['name']??'');if(!$n)throw new RuntimeException('Category name required.');db()->prepare('INSERT INTO categories(name,slug) VALUES(?,?)')->execute([$n,slugify($n)]);$msg='Category created.';}catch(Throwable $e){$msg=$e->getMessage();}}$rows=db()->query('SELECT c.*,COUNT(p.id) post_count FROM categories c LEFT JOIN posts p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();?><div class="topbar"><h1>Categories</h1></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><form class="row" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>New category<input name="name" required></label><button class="btn primary" style="align-self:end">Create category</button></form></div><div class="panel" style="margin-top:20px"><table class="table"><tr><th>Name</th><th>Slug</th><th>Posts</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slug'])?></td><td><?=e($r['post_count'])?></td><td><a class="btn danger" onclick="return confirm('Delete category? Posts will remain uncategorized.')" href="?delete=<?=$r['id']?>&csrf=<?=e(csrf())?>">Delete</a></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/_foot.php';
